output_text:
[
  {
    "id": "single_file_no_carts",
    "text": "Shopping carts are prohibited in single-file shelf aisles where a customer has only one cell of horizontal clearance.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_single_file",
    "text": "An agent may not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "mouth_north_no_cart",
    "text": "At the mouth of a pedestrian-only shelf aisle, moving north into the aisle is forbidden while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "northIntoPedestrianAisleWithCart": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "northIntoPedestrianAisleWithCart"
    }
  },
  {
    "id": "hand_only_shelf_pick",
    "text": "Items in a single-file shelf aisle must be picked without a cart in hand.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "A cart parked at the mouth of a pedestrian-only aisle must be reclaimed before leaving the store.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "pedestrianAisleMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "reclaimCartAtMouth": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "reclaimCartAtMouth"
    }
  },
  {
    "id": "return_to_cart_after_ped_pick",
    "text": "After picking an item from a pedestrian-only shelf aisle, the agent is obliged to return to and regain the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "pedestrianAisleItemPick": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "reclaimCartAtMouth": {
          "pre": {
            "and": [
              "pedestrianAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pedestrianAisleItemPick",
      "discharge": "reclaimCartAtMouth"
    }
  },
  {
    "id": "wide_lanes_require_cart",
    "text": "Except at the entrance/cart bay and pedestrian-aisle transfer mouths, customers should not walk through ordinary cart-suitable aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "entryOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartSuitableAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "singleFileShelfAisle"
            }
          ]
        },
        "ordinaryCartLane": {
          "and": [
            "cartSuitableAisle",
            {
              "not": "entryOrCartBay"
            },
            {
              "not": "pedestrianAisleMouth"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "ordinaryCartLane",
          {
            "not": "hasCart"
          },
          "MOVE"
        ]
      }
    }
  },
  {
    "id": "dont_push_cart_at_shelf_face",
    "text": "When pushing a cart next to a shelf, the agent must not move the cart directly toward the shelf face.",
    "abstraction": {
      "state_properties": {
        "shelfFaceNorth": "shelfN",
        "shelfFaceSouth": "shelfS",
        "shelfFaceEast": "shelfE",
        "shelfFaceWest": "shelfW"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              {
                "and": [
                  "shelfFaceNorth",
                  "N"
                ]
              },
              {
                "and": [
                  "shelfFaceSouth",
                  "S"
                ]
              },
              {
                "and": [
                  "shelfFaceEast",
                  "E"
                ]
              },
              {
                "and": [
                  "shelfFaceWest",
                  "W"
                ]
              }
            ]
          }
        ]
      }
    }
  }
]
